<?php

namespace Database\Seeders;

use App\Enums\CategoryStatus;
use App\Enums\ProductStatus;
use App\Models\Category;
use App\Models\Product;
use App\Models\Tenant;
use Illuminate\Database\Seeder;
use RuntimeException;

class DemoGarmentCatalogSeeder extends Seeder
{
    private const ASSETS = [
        'mint-tshirt.png' => '',
        'navy-hoodie.png' => '',
        'coral-polo.png' => '',
    ];

    public function run(): void
    {
        $tenant = Tenant::query()->where('domain', env('DEMO_TENANT_DOMAIN', 'demo.smartmirror.local'))->first();

        if (! $tenant) {
            return;
        }

        $this->writeAssets();

        $tops = Category::query()->updateOrCreate(
            ['tenant_id' => $tenant->id, 'slug' => 'tops'],
            ['name' => 'T-Shirts & Tops', 'status' => CategoryStatus::Active]
        );

        $products = [
            [
                'sku' => 'TSHIRT-001',
                'name' => 'Mint Smart Mirror T-Shirt',
                'description' => 'Transparent PNG demo T-shirt prepared for real-time AR fitting tests.',
                'unit_price' => 799,
                'asset' => 'mint-tshirt.png',
                'sizes' => [
                    ['size_label' => 'S', 'shoulder_width_cm' => 42, 'chest_width_cm' => 48, 'height_cm' => 66, 'sort_order' => 0],
                    ['size_label' => 'M', 'shoulder_width_cm' => 44, 'chest_width_cm' => 51, 'height_cm' => 69, 'sort_order' => 1],
                    ['size_label' => 'L', 'shoulder_width_cm' => 46, 'chest_width_cm' => 54, 'height_cm' => 72, 'sort_order' => 2],
                ],
            ],
            [
                'sku' => 'HOODIE-001',
                'name' => 'Navy Smart Mirror Hoodie',
                'description' => 'Transparent PNG hoodie with long sleeves for pose and overlay testing.',
                'unit_price' => 1299,
                'asset' => 'navy-hoodie.png',
                'sizes' => [
                    ['size_label' => 'M', 'shoulder_width_cm' => 45, 'chest_width_cm' => 55, 'height_cm' => 70, 'sort_order' => 0],
                    ['size_label' => 'L', 'shoulder_width_cm' => 47, 'chest_width_cm' => 58, 'height_cm' => 73, 'sort_order' => 1],
                    ['size_label' => 'XL', 'shoulder_width_cm' => 49, 'chest_width_cm' => 61, 'height_cm' => 76, 'sort_order' => 2],
                ],
            ],
            [
                'sku' => 'POLO-001',
                'name' => 'Coral Smart Mirror Polo',
                'description' => 'Transparent PNG polo shirt for switching between catalog garments.',
                'unit_price' => 949,
                'asset' => 'coral-polo.png',
                'sizes' => [
                    ['size_label' => 'S', 'shoulder_width_cm' => 41, 'chest_width_cm' => 47, 'height_cm' => 65, 'sort_order' => 0],
                    ['size_label' => 'M', 'shoulder_width_cm' => 43, 'chest_width_cm' => 50, 'height_cm' => 68, 'sort_order' => 1],
                    ['size_label' => 'L', 'shoulder_width_cm' => 45, 'chest_width_cm' => 53, 'height_cm' => 71, 'sort_order' => 2],
                ],
            ],
        ];

        foreach ($products as $item) {
            $product = Product::withTrashed()->firstOrNew([
                'tenant_id' => $tenant->id,
                'sku' => $item['sku'],
            ]);

            if ($product->trashed()) {
                $product->restore();
            }

            $assetUrl = '/demo-garments/'.$item['asset'];

            $product->fill([
                'category_id' => $tops->id,
                'name' => $item['name'],
                'description' => $item['description'],
                'base_image_url' => $assetUrl,
                'texture_image_url' => $assetUrl,
                'unit_price' => $item['unit_price'],
                'currency' => 'EGP',
                'status' => ProductStatus::Active,
            ])->save();

            $labels = [];

            foreach ($item['sizes'] as $size) {
                $labels[] = $size['size_label'];
                $product->sizingCharts()->updateOrCreate(
                    ['size_label' => $size['size_label']],
                    $size
                );
            }

            $product->sizingCharts()->whereNotIn('size_label', $labels)->delete();
        }
    }

    private function writeAssets(): void
    {
        $directory = public_path('demo-garments');

        if (! is_dir($directory) && ! mkdir($directory, 0755, true) && ! is_dir($directory)) {
            throw new RuntimeException('Unable to create the demo garment asset directory.');
        }

        foreach (self::ASSETS as $filename => $encoded) {
            $bytes = base64_decode($encoded, true);

            if ($bytes === false) {
                throw new RuntimeException('Unable to decode demo garment asset: '.$filename);
            }

            if (file_put_contents($directory.'/'.$filename, $bytes) === false) {
                throw new RuntimeException('Unable to write demo garment asset: '.$filename);
            }
        }
    }
}
